def best_reflections(comp):
    res=[]
    # vertical 2c axis k, horizontal 2r axis k
    for typ in 'vh':
        vals=[2*(p[1] if typ=='v' else p[0]) for p in comp]
        for k in range(min(vals)-2,max(vals)+3):
            rem=[]
            for r,c in comp:
                p=(r,k-c) if typ=='v' else (k-r,c)
                if p not in comp: rem.append((r,c))
            res.append((len(rem),typ,k,rem))
    return sorted(res)
